models = {'A': (0.92, 0.70, 0.95), 'B': (0.91, 0.86, 0.80), 'C': (0.94, 0.95, 0.45)}   # accuracy, precision, recall
def f1(p, r):
    return 2 * p * r / (p + r)

print({k: round(f1(v[1], v[2]), 3) for k, v in models.items()})
print(max(models, key=lambda k: f1(models[k][1], models[k][2])))
# prints: {'A': 0.806, 'B': 0.829, 'C': 0.611}
# prints: B

metric_for = {'spam filter (false positive costly)': 'precision', 'fraud screening (false negative costly)': 'recall', 'both matter': 'F1'}
for problem, metric in metric_for.items():
    print(problem, '->', metric)
# prints: spam filter (false positive costly) -> precision
# prints: fraud screening (false negative costly) -> recall
# prints: both matter -> F1
